def count_even_substrings(s):
    n = len(s)
    count = 0
    for i in range(n):
        for j in range(i, n):
            if int(s[i:j+1]) % 2 == 0:
                count += 1
    return count

# Read input
n = int(input())
s = input()

# Calculate and print the result
print(count_even_substrings(s))
